/** Canonical Trigger copies against released callbacks; no production Target dispatch required. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeCopifierTriggerWorldChecks {
 private static final BlockPos POS=new BlockPos(19400,82,19400);private static int checks;
 private static void need(boolean value,String text){checks++;if(!value)throw new AssertionError("Copied Trigger: "+text);}
 private static NativeTriggerBlockEntity at(ServerLevel world,BlockPos pos){return (NativeTriggerBlockEntity)world.getBlockEntity(pos);}
 private static NativeTriggerBlockEntity put(ServerLevel world,BlockPos pos,int meta,CompoundTag tag){world.getChunkAt(pos);world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);world.setBlock(pos,VandorLabsBootstrap.TRIGGER_BLOCK.get().defaultBlockState().setValue(ProgrammableBlock.FACING,Direction.from3DDataValue((meta&7)%6)),18);var owner=at(world,pos);var input=tag.copy();input.putString("CopiedTriggerMarker","retained");input.putByteArray("CopiedTriggerPayload",new byte[65536]);var cap=new CompoundTag();cap.putString("Owner","opaque:trigger");input.put("ForgeCaps",cap);owner.loadWithComponents(input,world.registryAccess());owner.onLoad();return owner;}
 private static CompoundTag capture(NativeTriggerBlockEntity owner){return NativeCopifierTriggerEdit.capture(owner.copiedSettings());}
 private static void write(ServerLevel world)throws Exception{String reference=System.getProperty("vandorlabs.copifierTriggerReference");int count=0;try(var lines=new BufferedReader(new InputStreamReader(new GZIPInputStream(Files.newInputStream(Path.of(reference))),java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=lines.readLine())!=null){var row=JsonParser.parseString(line).getAsJsonObject();var owner=put(world,POS,row.get("meta").getAsInt(),TagParser.parseTag(row.get("target").getAsString()));var state=owner.getBlockState();var values=TagParser.parseTag(row.get("values").getAsString());var original=values.copy();need(capture(owner).equals(TagParser.parseTag(row.get("before").getAsString())),"Source initial case="+count);boolean result=owner.configureCopied(values);need(result==row.get("applied").getAsBoolean(),"Source result case="+count);need(capture(owner).equals(TagParser.parseTag(row.get("after").getAsString())),"Source final case="+count+" values="+values);var saved=owner.saveWithoutMetadata(world.registryAccess());var expected=TriggerState.read(new ModernHousingTags(TagParser.parseTag(row.get("saved").getAsString())),ModernFinishCatalog::storedChoice);need(java.util.Arrays.equals(owner.triggerState().artworkModes(),expected.artworkModes())&&java.util.Arrays.equals(owner.triggerState().artworkSpeeds(),expected.artworkSpeeds()),"retained playback case="+count);need(world.getBlockEntity(POS)==owner&&owner.getBlockState()==state&&values.equals(original),"identity/placement/clipboard case="+count);need(saved.getString("CopiedTriggerMarker").equals("retained")&&saved.getByteArray("CopiedTriggerPayload").length==65536&&saved.getCompound("ForgeCaps").getString("Owner").equals("opaque:trigger"),"opaque fields case="+count);int slot=TriggerState.visibleSlot(owner.triggerState().bands,owner.triggerState().exact,owner.signalLevel());int visible=slot==0?owner.settings().mainTexture:slot==1?owner.triggerState().low:slot==2?owner.triggerState().medium:owner.triggerState().on;ProgrammableBlockDialog.State visual=owner.getModelData().get(ProgrammableBlockEntity.SETTINGS);need(visual.mainTexture==visible&&visual.facesEnabled==owner.triggerState().frontOnly,"final immutable visual case="+count);count++;}}need(count==1064,"complete Source matrix");
 var owner=at(world,POS);var edit=new CompoundTag();edit.putInt("wall_texture",7);need(!java.util.concurrent.CompletableFuture.supplyAsync(()->owner.configureCopied(edit)).join(),"worker refused before world reads");var unknown=owner.saveWithoutMetadata(world.registryAccess());var modules=new CompoundTag();var item=new CompoundTag();item.putString("id","future:module");item.putByte("Count",(byte)1);modules.put("main",item);var forge=unknown.getCompound("ForgeData").copy();forge.put("VandorTransmitters",modules);unknown.put("ForgeData",forge);owner.loadWithComponents(unknown,world.registryAccess());var before=owner.saveWithoutMetadata(world.registryAccess());need(!owner.configureCopied(edit)&&owner.saveWithoutMetadata(world.registryAccess()).equals(before),"unsupported owner refused before metadata/Trigger installation");
 var clean=put(world,POS,2,new CompoundTag());need(clean.configureCopied(edit)&&clean.settings().mainTexture==7,"saved selected edit");var bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();bean.setThreadAllocatedMemoryEnabled(true);long thread=Thread.currentThread().threadId();for(int i=0;i<300;i++)clean.copiedSettings();long start=bean.getThreadAllocatedBytes(thread);for(int i=0;i<1000;i++)clean.saveWithoutMetadata(world.registryAccess());long full=bean.getThreadAllocatedBytes(thread)-start;start=bean.getThreadAllocatedBytes(thread);for(int i=0;i<1000;i++)clean.copiedSettings();long bounded=bean.getThreadAllocatedBytes(thread)-start;need(bounded<full/2,"bounded choices avoid opaque payload serialization");System.out.println("[vandorlabs][copifier-trigger] allocation PASS fullBytes="+full+" boundedBytes="+bounded);
 var retired=clean;world.setBlock(POS,Blocks.AIR.defaultBlockState(),18);need(!retired.configureCopied(edit),"retired identity refused");clean=put(world,POS,2,new CompoundTag());need(clean.configureCopied(edit),"restart fixture copy");world.setChunkForced(POS.getX()>>4,POS.getZ()>>4,true);
 }
 private static void read(ServerLevel world){world.getChunkAt(POS);var owner=at(world,POS);need(owner!=null&&owner.settings().mainTexture==7,"configured choice restart");var saved=owner.saveWithoutMetadata(world.registryAccess());need(saved.getString("CopiedTriggerMarker").equals("retained")&&saved.getByteArray("CopiedTriggerPayload").length==65536,"opaque payload restart");need(saved.getCompound("ForgeCaps").getString("Owner").equals("opaque:trigger"),"capability restart");}
 @SubscribeEvent public static void started(ServerStartedEvent event)throws Exception{var phase=System.getProperty("vandorlabs.transmitterPhase","");if(!phase.startsWith("copifier-trigger-"))return;var world=event.getServer().overworld();if(phase.endsWith("write"))write(world);else read(world);event.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][copifier-trigger] "+(phase.endsWith("write")?"write":"read")+" PASS checks="+checks);event.getServer().halt(false);}
}
